<section class="page-banner"><div class="container"><div class="section-label">SOCIETY MANAGEMENT</div><h1>Manage clubs</h1><p>Add societies, assign club leaders and control club visibility.</p></div></section><section class="section container"><?php require dirname(__DIR__).'/partials/admin_nav.php'; ?><div class="right-align"><a class="btn btn-primary" href="<?= e(url('admin/club/form')) ?>">+ Add club</a></div><div class="card panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>Club</th><th>Faculty</th><th>Leader</th><th>Members</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($clubs as $c): ?><tr><td><strong><?= e($c['name']) ?></strong><div class="small-muted"><?= e($c['category']) ?></div></td><td><?= e($c['faculty']) ?></td><td><?= e($c['leader_name']?:'Not assigned') ?></td><td><?= (int)$c['members'] ?></td><td><?= status_pill($c['status']) ?></td><td><div class="row-actions"><a href="<?= e(url('admin/club/form',['id'=>$c['id']])) ?>" class="btn btn-outline btn-sm">Edit</a><a href="<?= e(url('leader/members',['club_id'=>$c['id']])) ?>" class="btn btn-outline btn-sm">Members</a><form method="post" action="<?= e(url('admin/club/status')) ?>" data-confirm="Change this club's public visibility?"><?= csrf_field() ?><input type="hidden" name="club_id" value="<?= (int)$c['id'] ?>"><button name="status" value="<?= $c['status']==='approved'?'suspended':'approved' ?>" class="btn btn-outline btn-sm"><?= $c['status']==='approved'?'Suspend':'Approve' ?></button></form></div></td></tr><?php endforeach; ?><?php if(!$clubs): ?><tr><td colspan="6">No clubs yet.</td></tr><?php endif; ?></tbody></table></div></div></section>
